/**
 * Pure types of one experiment: the plan a digest freezes, the two arms, the
 * paired per-environment comparison, and the verdict, free of host-side
 * imports.
 *
 * @module @deepseek-ai/dsh-experiments/types
 */

import type { EnvironmentId, EnvironmentRunModel } from '@deepseek-ai/dsh-environments/types'
import type { TrajectorySink } from '@deepseek-ai/dsh-trajectories/types'

/** Role one arm plays in a comparison; both roles run the same cells. */
export type ExperimentArmRole = 'baseline' | 'candidate'

/**
 * Statistical choices frozen into the plan digest. They decide what the
 * comparison measures and what counts as promotable, so two plans that differ
 * in any of them are two experiments.
 */
export interface ExperimentThresholds {
  /** Resamples drawn per bootstrap interval. */
  readonly bootstrapResamples: number
  /** Coverage of every reported interval, between `0` and `1`. */
  readonly confidenceLevel: number
  /** Certificate-rate delta the overall interval's lower bound must exceed to promote. */
  readonly minimumDelta: number
  /** Tokens one cell may spend; the projection the token budget is checked against. */
  readonly cellTokenCap: number
}

/**
 * One comparison to run: two arms over the same environments at the same
 * repetition indexes. A caller that froze the plan earlier passes the digest
 * it recorded back on {@link ExperimentPlan.digest}.
 */
export interface ExperimentPlan {
  /** Environments both arms run, each registered and named once. */
  readonly environments: readonly EnvironmentId[]
  /** Positive number of repetitions per environment and arm; repetition indexes start at zero. */
  readonly repetitions: number
  /** Model route of the reference arm. */
  readonly baseline: EnvironmentRunModel
  /** Model route of the arm under test. */
  readonly candidate: EnvironmentRunModel
  /** Existing absolute directory under which every cell gets its own fresh workspace directory. */
  readonly workspaceRoot: string
  /** Digest the caller froze earlier; a value the recomputed digest does not equal is refused. */
  readonly digest?: string
  /** Aborts the remaining cells when it fires; started cells abort through the runner. */
  readonly signal?: AbortSignal
  /** Destination of the result line; absent writes nothing and leaves the sessions as the only record. */
  readonly sink?: TrajectorySink
}

/** One arm as it ran: its model route and the stamp `group` its sessions carry. */
export interface ExperimentArm {
  /** Model route every cell of this arm ran. */
  readonly model: EnvironmentRunModel
  /** `experiment-<digest>-<role>`, written into the `environment/run` stamp of every session of this arm. */
  readonly group: string
}

/** Both arms of one experiment. */
export interface ExperimentArms {
  readonly baseline: ExperimentArm
  readonly candidate: ExperimentArm
}

/** Percentile bootstrap interval of a delta at the plan's confidence level. */
export interface ConfidenceInterval {
  readonly lower: number
  readonly upper: number
}

/**
 * One environment's paired comparison. Every rate, mean, and delta covers the
 * paired repetitions alone, so a repetition an arm failed to report changes
 * `pairs` and `unpaired` rather than silently shifting a rate.
 */
export interface ExperimentCell {
  readonly environment: EnvironmentId
  /** Repetition indexes both arms reported. */
  readonly pairs: number
  /** Repetition indexes that did not pair because an arm produced no report. */
  readonly unpaired: number
  /** Certified fraction of the baseline arm over the paired repetitions, `0` without pairs. */
  readonly baselineRate: number
  /** Certified fraction of the candidate arm over the paired repetitions, `0` without pairs. */
  readonly candidateRate: number
  /** `candidateRate - baselineRate`. */
  readonly delta: number
  /** Bootstrap interval of `delta`, absent without pairs. */
  readonly interval?: ConfidenceInterval
  /** Candidate mean attempts minus baseline mean attempts over the paired repetitions. */
  readonly attemptsDelta: number
  /** Candidate minus baseline input tokens summed over the paired repetitions. */
  readonly inputTokenDelta: number
  /** Candidate minus baseline output tokens summed over the paired repetitions. */
  readonly outputTokenDelta: number
}

/** Model usage summed over every reported cell of both arms, paired or not. */
export interface ExperimentSpend {
  readonly inputTokens: number
  readonly outputTokens: number
}

/** What the overall interval says about the candidate. */
export type ExperimentVerdict = 'promote' | 'reject' | 'inconclusive'

/**
 * Outcome of one experiment. The sessions grouped by `arms` carry the durable
 * evidence; this record is the fold over them.
 */
export interface ExperimentResult {
  /** Content digest of the frozen plan; both arm groups carry it. */
  readonly digest: string
  /** The two arms and the stamp group each ran under. */
  readonly arms: ExperimentArms
  /** One entry per environment, in plan order. */
  readonly cells: readonly ExperimentCell[]
  /** Paired repetition indexes over every environment; the bootstrap's units. */
  readonly seedsPaired: number
  /** Certificate-rate delta over every paired repetition, `0` without pairs. */
  readonly delta: number
  /** Bootstrap interval of `delta`, absent without pairs; the verdict reads it. */
  readonly interval?: ConfidenceInterval
  /** Model usage of both arms together. */
  readonly spend: ExperimentSpend
  /** Thresholds the digest froze, restated so a stored result is readable alone. */
  readonly thresholds: ExperimentThresholds
  readonly verdict: ExperimentVerdict
}

/**
 * Freezing one experiment plan: the content digest computed before any cell
 * runs, and the stamp `group` each arm's sessions carry so a later fold can
 * find them in the logs.
 *
 * @module @deepseek-ai/dsh-experiments/plan
 */

import { createHash } from 'node:crypto'
import type { ExperimentArmRole, ExperimentPlan, ExperimentThresholds } from './types.ts'

/**
 * Group namespace this package owns. A `group` starting with it names an
 * experiment arm, so no other producer may mint one.
 */
export const EXPERIMENT_GROUP_PREFIX = 'experiment-'

/** Self-declared version of the digested plan fields; a change to them changes it. */
export const EXPERIMENT_PLAN_VERSION = 1

/** Arm roles in the order the digest and the runs take them. */
export const EXPERIMENT_ARM_ROLES: readonly ExperimentArmRole[] = ['baseline', 'candidate']

const GROUP_PATTERN = /^experiment-([0-9a-f]{64})-(baseline|candidate)$/

/**
 * Content digest of the fields that decide what an experiment measures: the
 * two arm routes in role order, the environment ids sorted so a caller's
 * listing order cannot change the identity, the repetition count, and the
 * thresholds. The deployment's token budget is deliberately absent: it bounds
 * what a deployment pays for, not what the comparison measures.
 * @param plan - the arms, environments, and repetitions to freeze.
 * @param thresholds - the resolved statistical choices to freeze with them.
 * @returns the SHA-256 hex digest; identical inputs give identical digests.
 */
export function planDigest(plan: ExperimentPlan, thresholds: ExperimentThresholds): string {
  const content = JSON.stringify({
    version: EXPERIMENT_PLAN_VERSION,
    arms: EXPERIMENT_ARM_ROLES.map(role => [role, plan[role].provider, plan[role].model]),
    environments: [...plan.environments].sort(),
    repetitions: plan.repetitions,
    thresholds: [
      thresholds.bootstrapResamples,
      thresholds.confidenceLevel,
      thresholds.minimumDelta,
      thresholds.cellTokenCap,
    ],
  })
  return createHash('sha256').update(content).digest('hex')
}

/**
 * Stamp `group` one arm's sessions carry.
 * @param digest - the frozen plan digest.
 * @param role - which arm the group names.
 * @returns `experiment-<digest>-<role>`.
 */
export function experimentGroup(digest: string, role: ExperimentArmRole): string {
  return `${EXPERIMENT_GROUP_PREFIX}${digest}-${role}`
}

/**
 * Read a group minted by {@link experimentGroup}.
 * @param group - a stamp group from an `environment/run` event.
 * @returns the digest and role, or `undefined` for a group outside this package's namespace or malformed inside it.
 */
export function parseExperimentGroup(group: string): { digest: string; role: ExperimentArmRole } | undefined {
  const match = GROUP_PATTERN.exec(group)
  if (match === null) return undefined
  return { digest: match[1] as string, role: match[2] as ExperimentArmRole }
}

/**
 * Tokens a plan may spend at its per-cell cap: every environment, every
 * repetition, on both arms.
 * @param plan - the environments and repetitions to project.
 * @param cellTokenCap - tokens one cell may spend.
 * @returns the projected ceiling the token budget is checked against.
 */
export function projectedTokens(plan: ExperimentPlan, cellTokenCap: number): number {
  return plan.environments.length * plan.repetitions * EXPERIMENT_ARM_ROLES.length * cellTokenCap
}

/**
 * The paired bootstrap: percentile confidence intervals over per-environment
 * strata of paired deltas, drawn by a generator seeded from the frozen plan
 * digest so the same plan over the same certificates always yields the same
 * interval.
 *
 * @module @deepseek-ai/dsh-experiments/statistics
 */

import type { ConfidenceInterval } from './types.ts'

/** One environment's paired deltas, in repetition order. */
export interface DeltaStratum {
  /** Stratum identity; it seeds this stratum's generator together with the digest. */
  readonly key: string
  /** `candidate - baseline` per paired repetition; empty when nothing paired. */
  readonly deltas: readonly number[]
}

/** How to draw the intervals. */
export interface BootstrapRequest {
  /** Frozen plan digest; the only source of randomness in the fold. */
  readonly digest: string
  /** Resamples to draw, at least one. */
  readonly resamples: number
  /** Coverage of the reported intervals, between `0` and `1`. */
  readonly confidenceLevel: number
}

/** Intervals of one bootstrap pass. */
export interface BootstrapResult {
  /** One entry per requested stratum, in request order; absent for a stratum with no delta. */
  readonly strata: readonly (ConfidenceInterval | undefined)[]
  /** Interval of the mean over every drawn unit, absent when no stratum holds a delta. */
  readonly overall?: ConfidenceInterval
}

/** 32-bit FNV-1a hash of a UTF-16 code-unit sequence; the generator's seed. */
function fnv1a(text: string): number {
  let hash = 0x811c9dc5
  for (let index = 0; index < text.length; index += 1) {
    hash = Math.imul(hash ^ text.charCodeAt(index), 0x01000193)
  }
  return hash >>> 0
}

/** Mulberry32: a seeded generator of values in `[0, 1)`, used for every draw. */
function mulberry32(seed: number): () => number {
  let state = seed
  return () => {
    state = (state + 0x6d2b79f5) >>> 0
    let mixed = Math.imul(state ^ (state >>> 15), state | 1)
    mixed ^= mixed + Math.imul(mixed ^ (mixed >>> 7), mixed | 61)
    return ((mixed ^ (mixed >>> 14)) >>> 0) / 0x100000000
  }
}

/** Value at a quantile of an ascending sample, by nearest rank. */
function quantile(ascending: readonly number[], fraction: number): number {
  return ascending[Math.round(fraction * (ascending.length - 1))] as number
}

/** The percentile interval of one resampled distribution at a confidence level. */
function intervalOf(draws: number[], confidenceLevel: number): ConfidenceInterval {
  const ascending = [...draws].sort((left, right) => left - right)
  const tail = (1 - confidenceLevel) / 2
  return { lower: quantile(ascending, tail), upper: quantile(ascending, 1 - tail) }
}

/**
 * Draw percentile bootstrap intervals for every stratum and for their pooled
 * mean. Each resample draws, within every stratum, as many paired deltas as
 * that stratum holds, with replacement; the overall statistic of a resample is
 * the mean over every drawn delta, so a stratum weighs by its paired count and
 * an empty stratum contributes nothing rather than a zero.
 * @param strata - the per-environment paired deltas, in the order the result reports them.
 * @param request - the plan digest that seeds every draw, the resample count, and the confidence level.
 * @returns one interval per stratum and the overall interval, both absent where no delta was drawn.
 */
export function bootstrapIntervals(strata: readonly DeltaStratum[], request: BootstrapRequest): BootstrapResult {
  const units = strata.reduce((total, stratum) => total + stratum.deltas.length, 0)
  if (units === 0) return { strata: strata.map(() => undefined) }
  const generators = strata.map(stratum => mulberry32(fnv1a(`${request.digest}:${stratum.key}`)))
  const stratumDraws = strata.map(() => [] as number[])
  const overallDraws: number[] = []
  for (let resample = 0; resample < request.resamples; resample += 1) {
    let pooled = 0
    strata.forEach((stratum, index) => {
      if (stratum.deltas.length === 0) return
      const next = generators[index] as () => number
      let sum = 0
      for (let draw = 0; draw < stratum.deltas.length; draw += 1) {
        sum += stratum.deltas[Math.floor(next() * stratum.deltas.length)] as number
      }
      ;(stratumDraws[index] as number[]).push(sum / stratum.deltas.length)
      pooled += sum
    })
    overallDraws.push(pooled / units)
  }
  return {
    strata: strata.map((stratum, index) => (
      stratum.deltas.length === 0 ? undefined : intervalOf(stratumDraws[index] as number[], request.confidenceLevel)
    )),
    overall: intervalOf(overallDraws, request.confidenceLevel),
  }
}

/**
 * Folding two arms' fleet reports into one `ExperimentResult`: cells pair by
 * environment and repetition index, every statistic covers the paired
 * repetitions alone, and the verdict is one rule over the overall interval.
 *
 * @module @deepseek-ai/dsh-experiments/fold
 */

import type { EnvironmentRunReport } from '@deepseek-ai/dsh-environment-runner/types'
import type { EnvironmentId } from '@deepseek-ai/dsh-environments/types'
import type { FleetRunReport } from '@deepseek-ai/dsh-fleet/types'
import { bootstrapIntervals } from './statistics.ts'
import type { DeltaStratum } from './statistics.ts'
import type {
  ConfidenceInterval,
  ExperimentArms,
  ExperimentCell,
  ExperimentResult,
  ExperimentSpend,
  ExperimentThresholds,
  ExperimentVerdict,
} from './types.ts'

/** What one fold needs beside the two arms' reports. */
export interface ExperimentFoldRequest {
  /** Frozen plan digest; it identifies the result and seeds every bootstrap draw. */
  readonly digest: string
  /** The arms, with the stamp group each ran under. */
  readonly arms: ExperimentArms
  /** Environments in plan order; the fold reports one cell per entry. */
  readonly environments: readonly EnvironmentId[]
  /** Repetition indexes each arm ran per environment. */
  readonly repetitions: number
  /** Thresholds the digest froze; the confidence level and minimum delta are read here. */
  readonly thresholds: ExperimentThresholds
  /** The baseline arm's fleet report. */
  readonly baseline: FleetRunReport
  /** The candidate arm's fleet report. */
  readonly candidate: FleetRunReport
}

/** Per-repetition sums over the paired repetitions of one environment. */
interface PairedTotals {
  readonly deltas: number[]
  baselineCertified: number
  candidateCertified: number
  attempts: number
  inputTokens: number
  outputTokens: number
}

/** Key of one cell inside an arm; the pairing is exactly this key matching across arms. */
function cellKey(environment: EnvironmentId, repetition: number): string {
  return `${environment}�${repetition}`
}

/** The runs one arm produced, keyed by cell; a cell the fleet kept as an error is absent. */
function reportsOf(report: FleetRunReport): Map<string, EnvironmentRunReport> {
  const reports = new Map<string, EnvironmentRunReport>()
  for (const outcome of report.cells) {
    if ('report' in outcome) reports.set(cellKey(outcome.cell.environment, outcome.cell.repetition), outcome.report)
  }
  return reports
}

/** Model usage summed over every reported cell of both arms. */
function spendOf(arms: readonly FleetRunReport[]): ExperimentSpend {
  let inputTokens = 0
  let outputTokens = 0
  for (const arm of arms) {
    for (const outcome of arm.cells) {
      if (!('report' in outcome)) continue
      inputTokens += outcome.report.usage?.inputTokens ?? 0
      outputTokens += outcome.report.usage?.outputTokens ?? 0
    }
  }
  return { inputTokens, outputTokens }
}

/** Accumulate one environment's paired repetitions from the two arms' runs. */
function pairedTotals(
  environment: EnvironmentId,
  repetitions: number,
  baseline: ReadonlyMap<string, EnvironmentRunReport>,
  candidate: ReadonlyMap<string, EnvironmentRunReport>,
): PairedTotals {
  const totals: PairedTotals = {
    deltas: [],
    baselineCertified: 0,
    candidateCertified: 0,
    attempts: 0,
    inputTokens: 0,
    outputTokens: 0,
  }
  for (let repetition = 0; repetition < repetitions; repetition += 1) {
    const key = cellKey(environment, repetition)
    const before = baseline.get(key)
    const after = candidate.get(key)
    if (before === undefined || after === undefined) continue
    const beforeCertified = before.certified ? 1 : 0
    const afterCertified = after.certified ? 1 : 0
    totals.deltas.push(afterCertified - beforeCertified)
    totals.baselineCertified += beforeCertified
    totals.candidateCertified += afterCertified
    totals.attempts += after.attempts.length - before.attempts.length
    totals.inputTokens += (after.usage?.inputTokens ?? 0) - (before.usage?.inputTokens ?? 0)
    totals.outputTokens += (after.usage?.outputTokens ?? 0) - (before.usage?.outputTokens ?? 0)
  }
  return totals
}

/** A mean over the paired repetitions, `0` when nothing paired. */
function perPair(total: number, pairs: number): number {
  return pairs === 0 ? 0 : total / pairs
}

/**
 * The verdict rule. `promote` is tested first, so a deployment configuring a
 * negative minimum delta still gets the promoting branch instead of an
 * order-dependent answer.
 */
function verdictOf(interval: ConfidenceInterval | undefined, minimumDelta: number): ExperimentVerdict {
  if (interval === undefined) return 'inconclusive'
  if (interval.lower > minimumDelta) return 'promote'
  if (interval.upper < 0) return 'reject'
  return 'inconclusive'
}

/**
 * Fold both arms' fleet reports into the experiment's record.
 * @param request - the frozen digest and arms, the environments and repetitions that were run, the thresholds, and the two reports.
 * @returns one cell per environment in plan order, the pooled delta and its interval, the spend, and the verdict.
 */
export function foldExperiment(request: ExperimentFoldRequest): ExperimentResult {
  const baseline = reportsOf(request.baseline)
  const candidate = reportsOf(request.candidate)
  const totals = request.environments.map(environment => (
    pairedTotals(environment, request.repetitions, baseline, candidate)
  ))
  const strata: DeltaStratum[] = request.environments.map((environment, index) => ({
    key: environment,
    deltas: (totals[index] as PairedTotals).deltas,
  }))
  const bootstrap = bootstrapIntervals(strata, {
    digest: request.digest,
    resamples: request.thresholds.bootstrapResamples,
    confidenceLevel: request.thresholds.confidenceLevel,
  })
  const cells: ExperimentCell[] = request.environments.map((environment, index) => {
    const total = totals[index] as PairedTotals
    const pairs = total.deltas.length
    const interval = bootstrap.strata[index]
    return {
      environment,
      pairs,
      unpaired: request.repetitions - pairs,
      baselineRate: perPair(total.baselineCertified, pairs),
      candidateRate: perPair(total.candidateCertified, pairs),
      delta: perPair(total.candidateCertified - total.baselineCertified, pairs),
      ...interval === undefined ? {} : { interval },
      attemptsDelta: perPair(total.attempts, pairs),
      inputTokenDelta: total.inputTokens,
      outputTokenDelta: total.outputTokens,
    }
  })
  const seedsPaired = cells.reduce((sum, cell) => sum + cell.pairs, 0)
  const pooled = totals.reduce((sum, total) => sum + total.candidateCertified - total.baselineCertified, 0)
  return {
    digest: request.digest,
    arms: request.arms,
    cells,
    seedsPaired,
    delta: perPair(pooled, seedsPaired),
    ...bootstrap.overall === undefined ? {} : { interval: bootstrap.overall },
    spend: spendOf([request.baseline, request.candidate]),
    thresholds: request.thresholds,
    verdict: verdictOf(bootstrap.overall, request.thresholds.minimumDelta),
  }
}

/**
 * Experiments: a paired comparison of two arms over fleet cells. A plan is
 * frozen by a content digest before any cell runs, both arms run through the
 * fleet at the same repetition indexes under groups derived from that digest,
 * and the paired certificate-rate delta is reported with a bootstrap interval
 * and a verdict. Nothing here calls a model. The
 * [experiments Agent Note](../../../.agents/notes/proposed/architecture/2026-09-05-experiments.md)
 * owns the design rationale.
 * @module @deepseek-ai/dsh-experiments
 */

import { Context, Service } from '@deepseek-ai/cordis'
import z from '@deepseek-ai/schemastery'
// Type-only: resolves ctx.environments.
import type {} from '@deepseek-ai/dsh-environments'
import type { EnvironmentId } from '@deepseek-ai/dsh-environments/types'
// Type-only: resolves ctx.fleet.
import type {} from '@deepseek-ai/dsh-fleet'
import type { FleetRunReport } from '@deepseek-ai/dsh-fleet/types'
import { HarnessError } from '@deepseek-ai/dsh-llm'
import type { TrajectorySink } from '@deepseek-ai/dsh-trajectories/types'
import { foldExperiment } from './fold.ts'
import { experimentGroup, planDigest, projectedTokens } from './plan.ts'
import type { ExperimentArm, ExperimentArms, ExperimentPlan, ExperimentResult, ExperimentThresholds } from './types.ts'

export type * from './types.ts'
export { foldExperiment } from './fold.ts'
export type { ExperimentFoldRequest } from './fold.ts'
export {
  EXPERIMENT_ARM_ROLES,
  EXPERIMENT_GROUP_PREFIX,
  experimentGroup,
  parseExperimentGroup,
  planDigest,
  projectedTokens,
} from './plan.ts'
export { bootstrapIntervals } from './statistics.ts'
export type { BootstrapRequest, BootstrapResult, DeltaStratum } from './statistics.ts'

declare module '@deepseek-ai/cordis' {
  interface Context {
    experiments: ExperimentService
  }
}

/** Stable error codes of a refused plan. */
export type ExperimentErrorCode = 'EXPERIMENT_INVALID_PLAN' | 'EXPERIMENT_PLAN_NOT_FROZEN' | 'EXPERIMENT_OVER_BUDGET'

/** Error returned by the experiment boundary for a plan that cannot run. */
export class ExperimentError extends HarnessError {
  /**
   * @param message - human-readable reason.
   * @param code - stable machine-routable classification.
   */
  // Keep the constructor to narrow HarnessError's string code at this boundary.
  // oxlint-disable-next-line typescript/no-useless-constructor -- type-only narrowing
  constructor(message: string, code: ExperimentErrorCode) {
    super(message, code)
  }
}

/** Deployment choices of the experiment service, validated from `cordis.yml`. */
export interface Config {
  /** Resamples drawn per bootstrap interval. */
  bootstrapResamples?: number
  /** Coverage of every reported interval, between `0` and `1`. */
  confidenceLevel?: number
  /** Certificate-rate delta the overall interval's lower bound must exceed to promote. */
  minimumDelta?: number
  /** Tokens one cell may spend; the plan's projection multiplies it by every cell of both arms. */
  cellTokenCap: number
  /** Tokens one plan's projection may reach; a plan projecting more is refused before it starts. */
  tokenBudget: number
}

/** The experiment service's choices with every default applied. */
export interface ResolvedConfig {
  /** The statistical choices the plan digest freezes. */
  readonly thresholds: ExperimentThresholds
  /** Tokens one plan's projection may reach; a deployment ceiling, outside the digest. */
  readonly tokenBudget: number
}

/**
 * Apply the experiment service's defaults to a validated config.
 * @param config - validated deployment config; the two token fields carry no default.
 * @returns the frozen thresholds and the deployment's token budget.
 */
export function resolveConfig(config: Config): ResolvedConfig {
  return {
    thresholds: {
      bootstrapResamples: config.bootstrapResamples ?? 1000,
      confidenceLevel: config.confidenceLevel ?? 0.95,
      minimumDelta: config.minimumDelta ?? 0,
      cellTokenCap: config.cellTokenCap,
    },
    tokenBudget: config.tokenBudget,
  }
}

/** Experiments (`ctx.experiments`): a frozen, paired, budgeted comparison of two arms. */
export class ExperimentService extends Service {
  static inject = ['environments', 'fleet']

  static Config: z<Config> = z.object({
    bootstrapResamples: z.natural().min(1).default(1000),
    confidenceLevel: z.number().min(0).max(1).default(0.95),
    minimumDelta: z.number().default(0),
    cellTokenCap: z.natural().min(1).required(),
    tokenBudget: z.natural().min(1).required(),
  })

  private readonly resolved: ResolvedConfig

  constructor(ctx: Context, config: Config) {
    super(ctx, 'experiments')
    this.resolved = resolveConfig(config)
  }

  /**
   * Freeze a plan, run both arms through the fleet at the same repetition
   * indexes, and fold the paired comparison. Every refusal happens before the
   * first cell runs; a cell the fleet kept as an error leaves its repetition
   * unpaired instead of failing the experiment.
   * @param plan - environments, repetitions, the two arm routes, the workspace root, an optional frozen digest, abort signal, and result sink.
   * @returns the digest, both arms with their stamp groups, one cell per environment, the pooled delta with its interval, the spend, and the verdict.
   * @throws {@link ExperimentError} for a plan that names no or a duplicate or
   *   unregistered environment, asks for no repetition, declares a digest its
   *   content does not freeze to, or projects more tokens than the budget.
   */
  async run(plan: ExperimentPlan): Promise<ExperimentResult> {
    const digest = this.freeze(plan)
    const arms: ExperimentArms = {
      baseline: { model: plan.baseline, group: experimentGroup(digest, 'baseline') },
      candidate: { model: plan.candidate, group: experimentGroup(digest, 'candidate') },
    }
    const baseline = await this.runArm(plan, arms.baseline)
    const candidate = await this.runArm(plan, arms.candidate)
    const result = foldExperiment({
      digest,
      arms,
      environments: plan.environments,
      repetitions: plan.repetitions,
      thresholds: this.resolved.thresholds,
      baseline,
      candidate,
    })
    await record(result, plan.sink)
    return result
  }

  /** Validate the plan, compute its digest, and check the projection against the budget. */
  private freeze(plan: ExperimentPlan): string {
    if (!Number.isInteger(plan.repetitions) || plan.repetitions < 1) {
      throw new ExperimentError(`repetitions must be a positive integer, got ${String(plan.repetitions)}`, 'EXPERIMENT_INVALID_PLAN')
    }
    if (plan.environments.length === 0) throw new ExperimentError('the plan names no environment', 'EXPERIMENT_INVALID_PLAN')
    const named = new Set<EnvironmentId>()
    for (const environment of plan.environments) {
      if (named.has(environment)) throw new ExperimentError(`environment "${environment}" is named twice`, 'EXPERIMENT_INVALID_PLAN')
      if (this.ctx.environments.get(environment) === undefined) {
        throw new ExperimentError(`environment "${environment}" is not registered`, 'EXPERIMENT_INVALID_PLAN')
      }
      named.add(environment)
    }
    const digest = planDigest(plan, this.resolved.thresholds)
    if (plan.digest !== undefined && plan.digest !== digest) {
      throw new ExperimentError(`the plan declares digest ${plan.digest} but freezes to ${digest}`, 'EXPERIMENT_PLAN_NOT_FROZEN')
    }
    const projected = projectedTokens(plan, this.resolved.thresholds.cellTokenCap)
    if (projected > this.resolved.tokenBudget) {
      throw new ExperimentError(`the plan projects ${projected} tokens over a budget of ${this.resolved.tokenBudget}`, 'EXPERIMENT_OVER_BUDGET')
    }
    return digest
  }

  /** Run one arm as one fleet run over the plan's environments under the arm's group. */
  private async runArm(plan: ExperimentPlan, arm: ExperimentArm): Promise<FleetRunReport> {
    return this.ctx.fleet.run({
      environments: { ids: plan.environments },
      models: [arm.model],
      repetitions: plan.repetitions,
      workspaceRoot: plan.workspaceRoot,
      group: arm.group,
      ...plan.signal === undefined ? {} : { signal: plan.signal },
    })
  }
}

/** Write the result as one JSON line and close the sink exactly once. */
async function record(result: ExperimentResult, sink?: TrajectorySink): Promise<void> {
  if (sink === undefined) return
  try {
    await sink.write(`${JSON.stringify(result)}\n`)
  } finally {
    await sink.close()
  }
}

export default ExperimentService

/**
 * Package-owned invariant: this package owns the `experiment-` stamp `group`
 * namespace, and a fold finds an experiment's sessions by parsing that group
 * back into a digest and an arm role. Every `environment/run` stamp whose
 * group starts with the prefix must therefore parse, so a session stamped with
 * a lookalike group can never be silently attributed to an arm or silently
 * dropped from one.
 *
 * @module @deepseek-ai/dsh-experiments/invariant
 */

import type { Context } from '@deepseek-ai/cordis'
import { decodeEnvironmentRun } from '@deepseek-ai/dsh-environments'
import type { InvariantFailure, InvariantInstaller } from '@deepseek-ai/dsh-invariants'
import type { Session, SessionEvent } from '@deepseek-ai/dsh-session'
import { EXPERIMENT_GROUP_PREFIX, parseExperimentGroup } from './plan.ts'

const PACKAGE_NAME = '@deepseek-ai/dsh-experiments'

/** Cordis companion plugin name. */
export const name = 'experiments-invariant'
/** Service required before the companion can reserve package ownership. */
export const inject = ['invariants']

/**
 * Report a stamp that claims this package's group namespace without naming an
 * arm of a frozen plan.
 * @param event - the candidate session event.
 * @param fail - the reporter for a broken relation.
 */
export function checkStampGroup(event: SessionEvent, fail: InvariantFailure): void {
  if (event.type !== 'environment/run') return
  let group: string | undefined
  try {
    group = decodeEnvironmentRun(event.data)?.group
  } catch (_malformedStamp) {
    // The environments package owns the stamp payload at the durable boundary;
    // reporting its malformed events here would attribute them to this package.
    return
  }
  if (group === undefined || !group.startsWith(EXPERIMENT_GROUP_PREFIX)) return
  if (parseExperimentGroup(group) === undefined) {
    fail(`session event ${event.seq} stamps group "${group}" in the experiment namespace without a frozen digest and arm role`)
  }
}

/** Check existing sessions and every candidate event before Session publishes it. */
const install: InvariantInstaller = Object.assign((ctx: Context, fail: InvariantFailure) => {
  for (const session of ctx.sessions.list()) {
    for (const event of session.events) checkStampGroup(event, fail)
  }
  /* jscpd:ignore-start -- package companions share dispatch and registration plumbing */
  ctx.on('internal/dispatch', (_mode, eventName, args) => {
    if (eventName !== 'session/event') return
    const [, event] = args as [Session, SessionEvent]
    checkStampGroup(event, fail)
  }, { global: true })
}, { inject: ['sessions'] })

/**
 * Register the experiment-group invariant companion.
 * @param ctx - Cordis context carrying the invariant service.
 * @returns the installed registration's disposer after setup succeeds.
 */
export const apply = (ctx: Context): Promise<() => void> =>
  Promise.resolve(ctx.invariants.register(PACKAGE_NAME, install))
/* jscpd:ignore-end */

import { describe, expect, it } from 'vitest'
import { Context, Service } from '@deepseek-ai/cordis'
import type { EnvironmentRunReport } from '@deepseek-ai/dsh-environment-runner/types'
import { EnvironmentId } from '@deepseek-ai/dsh-environments'
import type { EnvironmentDefinition, EnvironmentId as EnvironmentIdType, EnvironmentRunModel } from '@deepseek-ai/dsh-environments/types'
import type { FleetCell, FleetCellOutcome, FleetPlan, FleetRunReport } from '@deepseek-ai/dsh-fleet/types'
import { SessionId } from '@deepseek-ai/dsh-session'
import type { TrajectorySink } from '@deepseek-ai/dsh-trajectories/types'
import { CheckId } from '@deepseek-ai/dsh-verification'
import ExperimentService, {
  EXPERIMENT_ARM_ROLES,
  EXPERIMENT_GROUP_PREFIX,
  ExperimentError,
  experimentGroup,
  foldExperiment,
  parseExperimentGroup,
  planDigest,
  projectedTokens,
  resolveConfig,
} from '@deepseek-ai/dsh-experiments'
import type { Config, ExperimentPlan, ExperimentThresholds } from '@deepseek-ai/dsh-experiments'

declare module '@deepseek-ai/dsh-environments/types' {
  interface EnvironmentKindMap {
    smoke: Record<string, never>
  }
}

const HEX = 'c'.repeat(64)
const ROUND_TRIP = EnvironmentId('smoke:round-trip')
const UNSATISFIABLE = EnvironmentId('smoke:unsatisfiable')
const BASELINE = { provider: 'mock', model: 'base' }
const CANDIDATE = { provider: 'mock', model: 'next' }

/** One cell's run as the stub fleet reports it; `undefined` makes the cell an error outcome. */
interface CellShape {
  certified: boolean
  attempts?: number
  usage?: { inputTokens: number; outputTokens: number }
}

type CellScript = (cell: FleetCell) => CellShape | undefined

function definition(id: EnvironmentIdType): EnvironmentDefinition {
  return {
    id,
    kind: 'smoke',
    name: id,
    description: id,
    task: { prompt: `Run ${id}.` },
    checks: [{ id: CheckId('check'), outcome: 'passes', run: 'true' }],
    heldOut: false,
    owner: '@deepseek-ai/dsh-experiments-tests',
    provenance: 'curated',
    detail: {},
  }
}

class StubEnvironments extends Service {
  readonly definitions = [definition(ROUND_TRIP), definition(UNSATISFIABLE)]
  constructor(ctx: Context) {
    super(ctx, 'environments')
  }
  get(id: string): EnvironmentDefinition | undefined {
    return this.definitions.find(candidate => candidate.id === id)
  }
}

function runReport(cell: FleetCell, group: string, shape: CellShape): EnvironmentRunReport {
  const attempts = shape.attempts ?? 1
  return {
    environment: cell.environment,
    sessionId: SessionId(`${group}-${cell.environment}-${cell.repetition}`),
    stamp: {
      kind: 'environment/run',
      version: 1,
      environmentId: cell.environment,
      environmentKind: 'smoke',
      heldOut: false,
      promptSha256: HEX,
      checksSha256: HEX,
      contentSha256: HEX,
      repetition: cell.repetition,
      group,
      model: cell.model,
      isolation: 'none',
    },
    attempts: Array.from({ length: attempts }, (_, index) => ({ attempt: index + 1, results: [], treeHash: HEX })),
    certified: shape.certified,
    ...shape.usage === undefined ? {} : { usage: shape.usage },
  }
}

/** Enumerate one arm's cells the way the fleet does and apply the script to each. */
function fleetReport(plan: FleetPlan, script: CellScript): FleetRunReport {
  const ids = 'ids' in plan.environments ? plan.environments.ids : []
  const model = plan.models[0] as EnvironmentRunModel
  const group = plan.group as string
  const cells: FleetCellOutcome[] = []
  for (const environment of ids) {
    for (let repetition = 0; repetition < plan.repetitions; repetition += 1) {
      const cell: FleetCell = { environment, model, repetition }
      const shape = script(cell)
      cells.push(shape === undefined
        ? { cell, error: { message: 'the cell could not boot' } }
        : { cell, report: runReport(cell, group, shape) })
    }
  }
  return { group, cells, leaderboard: [] }
}

class StubFleet extends Service {
  static current: StubFleet
  readonly plans: FleetPlan[] = []
  script: CellScript = () => ({ certified: true })
  constructor(ctx: Context) {
    super(ctx, 'fleet')
    StubFleet.current = this
  }
  run(plan: FleetPlan): Promise<FleetRunReport> {
    this.plans.push(plan)
    return Promise.resolve(fleetReport(plan, cell => this.script(cell)))
  }
}

/** A sink recording what one run wrote and how often it closed. */
function recordingSink(failWrite = false): TrajectorySink & { lines: string[]; closes: number } {
  const sink = {
    lines: [] as string[],
    closes: 0,
    write(line: string): void {
      if (failWrite) throw new Error('the sink is full')
      sink.lines.push(line)
    },
    close(): void {
      sink.closes += 1
    },
  }
  return sink
}

interface Harness {
  ctx: Context
  /** A complete two-environment plan; overrides replace any field. */
  plan: (overrides?: Partial<ExperimentPlan>) => ExperimentPlan
}

async function harness(config: Partial<Config> = {}): Promise<Harness> {
  const ctx = new Context()
  for (const stub of [StubEnvironments, StubFleet]) await ctx.plugin(stub)
  await ctx.plugin(ExperimentService, { cellTokenCap: 1000, tokenBudget: 1_000_000, ...config })
  const plan = (overrides: Partial<ExperimentPlan> = {}): ExperimentPlan => ({
    environments: [ROUND_TRIP, UNSATISFIABLE],
    repetitions: 2,
    baseline: BASELINE,
    candidate: CANDIDATE,
    workspaceRoot: '/tmp/experiment',
    ...overrides,
  })
  return { ctx, plan }
}

/** Certified when the cell's arm is the named route. */
function certifiedFor(model: EnvironmentRunModel): CellScript {
  return cell => ({ certified: cell.model.model === model.model })
}

describe('ExperimentService', () => {
  it('freezes the plan, runs both arms at paired repetitions under digest-derived groups, and folds a null comparison', async () => {
    const { ctx, plan } = await harness()
    const result = await ctx.experiments.run(plan({ baseline: BASELINE, candidate: BASELINE }))

    const digest = planDigest(plan({ baseline: BASELINE, candidate: BASELINE }), result.thresholds)
    expect(result.digest).toBe(digest)
    expect(result.arms).toEqual({
      baseline: { model: BASELINE, group: `${EXPERIMENT_GROUP_PREFIX}${digest}-baseline` },
      candidate: { model: BASELINE, group: `${EXPERIMENT_GROUP_PREFIX}${digest}-candidate` },
    })
    expect(EXPERIMENT_ARM_ROLES.map(role => experimentGroup(digest, role)))
      .toEqual([result.arms.baseline.group, result.arms.candidate.group])

    const { plans } = StubFleet.current
    expect(plans).toHaveLength(2)
    expect(plans.map(fleet => fleet.group)).toEqual([result.arms.baseline.group, result.arms.candidate.group])
    for (const fleet of plans) {
      expect(fleet.environments).toEqual({ ids: [ROUND_TRIP, UNSATISFIABLE] })
      expect(fleet.repetitions).toBe(2)
      expect(fleet.workspaceRoot).toBe('/tmp/experiment')
      expect(fleet).not.toHaveProperty('signal')
    }
    expect(plans.map(fleet => fleet.models)).toEqual([[BASELINE], [BASELINE]])

    expect(result.seedsPaired).toBe(4)
    expect(result.delta).toBe(0)
    expect(result.interval).toEqual({ lower: 0, upper: 0 })
    expect(result.verdict).toBe('inconclusive')
    expect(result.cells).toEqual([
      { environment: ROUND_TRIP, pairs: 2, unpaired: 0, baselineRate: 1, candidateRate: 1, delta: 0, interval: { lower: 0, upper: 0 }, attemptsDelta: 0, inputTokenDelta: 0, outputTokenDelta: 0 },
      { environment: UNSATISFIABLE, pairs: 2, unpaired: 0, baselineRate: 1, candidateRate: 1, delta: 0, interval: { lower: 0, upper: 0 }, attemptsDelta: 0, inputTokenDelta: 0, outputTokenDelta: 0 },
    ])
    expect(result.spend).toEqual({ inputTokens: 0, outputTokens: 0 })
    expect(result.thresholds).toEqual({ bootstrapResamples: 1000, confidenceLevel: 0.95, minimumDelta: 0, cellTokenCap: 1000 })
  })

  it('promotes a candidate that certifies everywhere the baseline fails, and reports its attempts and token deltas', async () => {
    const { ctx, plan } = await harness()
    StubFleet.current.script = (cell) => {
      const candidate = cell.model.model === CANDIDATE.model
      return {
        certified: candidate,
        attempts: candidate ? 1 : 3,
        usage: { inputTokens: candidate ? 40 : 10, outputTokens: candidate ? 4 : 1 },
      }
    }
    const result = await ctx.experiments.run(plan())

    expect(result.verdict).toBe('promote')
    expect(result.delta).toBe(1)
    expect(result.interval).toEqual({ lower: 1, upper: 1 })
    expect(result.cells[0]).toEqual({
      environment: ROUND_TRIP,
      pairs: 2,
      unpaired: 0,
      baselineRate: 0,
      candidateRate: 1,
      delta: 1,
      interval: { lower: 1, upper: 1 },
      attemptsDelta: -2,
      inputTokenDelta: 60,
      outputTokenDelta: 6,
    })
    expect(result.spend).toEqual({ inputTokens: 200, outputTokens: 20 })
  })

  it('rejects a candidate strictly worse than the baseline, and stays inconclusive under a minimum delta it does not clear', async () => {
    const { ctx, plan } = await harness()
    StubFleet.current.script = certifiedFor(BASELINE)
    await expect(ctx.experiments.run(plan())).resolves.toMatchObject({
      verdict: 'reject',
      delta: -1,
      interval: { lower: -1, upper: -1 },
    })

    const demanding = await harness({ minimumDelta: 1 })
    StubFleet.current.script = certifiedFor(CANDIDATE)
    await expect(demanding.ctx.experiments.run(demanding.plan())).resolves.toMatchObject({ delta: 1, verdict: 'inconclusive' })
  })

  it('leaves a repetition an arm did not report out of every statistic and counts it as unpaired', async () => {
    const { ctx, plan } = await harness()
    StubFleet.current.script = (cell) => {
      if (cell.environment === UNSATISFIABLE) return undefined
      if (cell.model.model === CANDIDATE.model && cell.repetition === 1) return undefined
      return { certified: cell.model.model === CANDIDATE.model, usage: { inputTokens: 7, outputTokens: 2 } }
    }
    const result = await ctx.experiments.run(plan())

    expect(result.seedsPaired).toBe(1)
    expect(result.cells).toEqual([
      { environment: ROUND_TRIP, pairs: 1, unpaired: 1, baselineRate: 0, candidateRate: 1, delta: 1, interval: { lower: 1, upper: 1 }, attemptsDelta: 0, inputTokenDelta: 0, outputTokenDelta: 0 },
      { environment: UNSATISFIABLE, pairs: 0, unpaired: 2, baselineRate: 0, candidateRate: 0, delta: 0, attemptsDelta: 0, inputTokenDelta: 0, outputTokenDelta: 0 },
    ])
    expect(result.cells[1]).not.toHaveProperty('interval')
    expect(result.spend).toEqual({ inputTokens: 21, outputTokens: 6 })
    expect(result.verdict).toBe('promote')
  })

  it('stays inconclusive with no interval when nothing paired at all', async () => {
    const { ctx, plan } = await harness()
    StubFleet.current.script = () => undefined
    const result = await ctx.experiments.run(plan())

    expect(result.seedsPaired).toBe(0)
    expect(result.delta).toBe(0)
    expect(result).not.toHaveProperty('interval')
    expect(result.verdict).toBe('inconclusive')
    expect(result.cells.every(cell => cell.pairs === 0 && cell.unpaired === 2)).toBe(true)
  })

  it('accepts a digest the caller froze earlier and refuses one the plan no longer freezes to', async () => {
    const { ctx, plan } = await harness()
    const frozen = planDigest(plan(), resolveConfig({ cellTokenCap: 1000, tokenBudget: 1_000_000 }).thresholds)
    await expect(ctx.experiments.run(plan({ digest: frozen }))).resolves.toMatchObject({ digest: frozen })

    const edited = ctx.experiments.run(plan({ digest: frozen, repetitions: 3 }))
    await expect(edited).rejects.toBeInstanceOf(ExperimentError)
    await expect(edited).rejects.toMatchObject({ code: 'EXPERIMENT_PLAN_NOT_FROZEN' })
    expect(StubFleet.current.plans).toHaveLength(2)
  })

  it('refuses a plan it cannot start before any fleet call', async () => {
    const { ctx, plan } = await harness({ tokenBudget: 4000 })
    const refusals: [ExperimentPlan, string][] = [
      [plan({ repetitions: 0 }), 'EXPERIMENT_INVALID_PLAN'],
      [plan({ repetitions: 1.5 }), 'EXPERIMENT_INVALID_PLAN'],
      [plan({ environments: [] }), 'EXPERIMENT_INVALID_PLAN'],
      [plan({ environments: [ROUND_TRIP, ROUND_TRIP] }), 'EXPERIMENT_INVALID_PLAN'],
      [plan({ environments: [EnvironmentId('smoke:missing')] }), 'EXPERIMENT_INVALID_PLAN'],
      [plan(), 'EXPERIMENT_OVER_BUDGET'],
    ]
    for (const [refused, code] of refusals) await expect(ctx.experiments.run(refused)).rejects.toMatchObject({ code })
    expect(StubFleet.current.plans).toEqual([])

    expect(projectedTokens(plan(), 1000)).toBe(4000)
    await expect(ctx.experiments.run(plan({ repetitions: 1 }))).resolves.toMatchObject({ seedsPaired: 2 })
  })

  it('passes the abort signal to both arms and writes the result through the sink exactly once', async () => {
    const { ctx, plan } = await harness()
    const controller = new AbortController()
    const sink = recordingSink()
    const result = await ctx.experiments.run(plan({ signal: controller.signal, sink }))

    expect(StubFleet.current.plans.every(fleet => fleet.signal === controller.signal)).toBe(true)
    expect(sink.closes).toBe(1)
    expect(sink.lines).toHaveLength(1)
    expect(JSON.parse(sink.lines[0] as string)).toEqual(JSON.parse(JSON.stringify(result)))
    expect(sink.lines[0]?.endsWith('\n')).toBe(true)
  })

  it('closes the sink when the write fails', async () => {
    const { ctx, plan } = await harness()
    const sink = recordingSink(true)
    await expect(ctx.experiments.run(plan({ sink }))).rejects.toThrow('the sink is full')
    expect(sink.closes).toBe(1)
  })

  it('folds the same reports into the same intervals, so a frozen plan replays', async () => {
    const { ctx, plan } = await harness()
    StubFleet.current.script = cell => ({ certified: cell.repetition % 2 === (cell.model.model === CANDIDATE.model ? 0 : 1) })
    const result = await ctx.experiments.run(plan({ repetitions: 4 }))
    const request = {
      digest: result.digest,
      arms: result.arms,
      environments: [ROUND_TRIP, UNSATISFIABLE],
      repetitions: 4,
      thresholds: result.thresholds,
      baseline: fleetReport(StubFleet.current.plans[0] as FleetPlan, cell => ({ certified: cell.repetition % 2 === 1 })),
      candidate: fleetReport(StubFleet.current.plans[1] as FleetPlan, cell => ({ certified: cell.repetition % 2 === 0 })),
    }
    expect(foldExperiment(request)).toEqual(result)
    expect(foldExperiment(request)).toEqual(foldExperiment(request))
    expect(result.interval?.lower).toBeLessThan(result.interval?.upper as number)
  })

  it('reads back the group it minted and ignores every group outside its namespace', async () => {
    const { ctx, plan } = await harness()
    const result = await ctx.experiments.run(plan())
    expect(parseExperimentGroup(result.arms.candidate.group)).toEqual({ digest: result.digest, role: 'candidate' })
    expect(parseExperimentGroup('fleet-batch-1')).toBeUndefined()
    expect(parseExperimentGroup(`${EXPERIMENT_GROUP_PREFIX}not-a-digest-baseline`)).toBeUndefined()
  })

  it('resolves defaults once, at the boundary, and digests only what decides the comparison', () => {
    const thresholds: ExperimentThresholds = { bootstrapResamples: 1000, confidenceLevel: 0.95, minimumDelta: 0, cellTokenCap: 500 }
    expect(resolveConfig({ cellTokenCap: 500, tokenBudget: 9000 })).toEqual({ thresholds, tokenBudget: 9000 })
    expect(resolveConfig({ bootstrapResamples: 200, confidenceLevel: 0.9, minimumDelta: 0.05, cellTokenCap: 500, tokenBudget: 9000 }))
      .toEqual({ thresholds: { bootstrapResamples: 200, confidenceLevel: 0.9, minimumDelta: 0.05, cellTokenCap: 500 }, tokenBudget: 9000 })

    const ordered: ExperimentPlan = {
      environments: [ROUND_TRIP, UNSATISFIABLE],
      repetitions: 2,
      baseline: BASELINE,
      candidate: CANDIDATE,
      workspaceRoot: '/tmp/one',
    }
    const reordered: ExperimentPlan = { ...ordered, environments: [UNSATISFIABLE, ROUND_TRIP], workspaceRoot: '/tmp/other' }
    expect(planDigest(ordered, thresholds)).toBe(planDigest(reordered, thresholds))
    expect(planDigest(ordered, thresholds)).not.toBe(planDigest({ ...ordered, baseline: CANDIDATE }, thresholds))
    expect(planDigest(ordered, thresholds)).not.toBe(planDigest(ordered, { ...thresholds, minimumDelta: 0.1 }))
  })
})

